\begin{tikzpicture}[font=\sffamily, scale=0.9]

  % Beaker
  \draw[thick] (1,0) -- (1,4) -- (1.1,4) -- (1.1,0.2) -- (5.9,0.2) -- (5.9,4) -- (6,4) -- (6,0) -- cycle;

  % Distilled water inside beaker
  \dotregion{1.1}{0.2}{5.9}{3.2}
  \node at (2.2, 1.5) [align=center] {distilled\\water};

  % Visking tubing bag (semi-permeable membrane)
  % Drawn as a rounded sack hanging from the capillary tube
  \draw[thick, fill=white] (3.1, 2.5) 
    .. controls (2.8, 2.5) and (2.5, 2.0) .. (2.5, 1.2)
    .. controls (2.5, 0.4) and (3.0, 0.3) .. (3.5, 0.3)
    .. controls (4.0, 0.3) and (4.5, 0.4) .. (4.5, 1.2)
    .. controls (4.5, 2.0) and (4.2, 2.5) .. (3.9, 2.5)
    -- cycle;

  % Concentrated sucrose solution inside bag and extending up capillary tube
  \dotregion{3.101}{0.4}{3.899}{2.499}
  \dotregion{3.35}{2.5}{3.65}{6.5}

  % Capillary tube passing through a stopper or held somehow (just the tube shown)
  \draw[thick, fill=white] (3.35, 2.5) rectangle (3.65, 8.0);
  % Inner hollow line for tube sides
  \draw[thin] (3.35, 2.5) -- (3.35, 8.0);
  \draw[thin] (3.65, 2.5) -- (3.65, 8.0);

  % Liquid level at start (dashed line)
  \draw[thick, dashed] (3.35, 3.5) -- (3.65, 3.5);

  % Liquid level after 30 min
  \draw[thick] (3.35, 6.5) -- (3.65, 6.5);
  \fill[gray!50] (3.36, 3.51) rectangle (3.64, 6.49);
  % redraw fill cleanly over the liquid area
  \dotregion{3.36}{2.51}{3.64}{6.49}

  % Thread tying the bag around the capillary tube
  \draw[ultra thick] (3.25, 2.65) -- (3.75, 2.75);
  \draw[ultra thick] (3.25, 2.75) -- (3.75, 2.65);

  % Labels and pointers
  % 1. Capillary tube
  \draw[-latex] (5.2, 7.2) -- (3.66, 7.2);
  \node[right] at (5.2, 7.2) {capillary tube};

  % 2. Liquid level after 30 min
  \draw[-latex] (5.2, 6.5) -- (3.66, 6.5);
  \node[right] at (5.2, 6.5) {liquid level after 30 min};

  % 3. Liquid level at start
  \draw[-latex] (5.2, 3.5) -- (3.66, 3.5);
  \node[right] at (5.2, 3.5) {liquid level at start};

  % 4. Thread
  \draw[-latex] (1.8, 2.7) -- (3.25, 2.7);
  \node[left] at (1.8, 2.7) {thread};

  % 5. Visking tubing
  \draw[-latex] (1.8, 1.8) -- (2.65, 1.8);
  \node[left] at (1.8, 1.8) {Visking tubing};

  % 6. Concentrated sucrose solution
  \draw[-latex] (1.8, 1.0) -- (3.0, 1.0);
  \node[left] at (1.8, 1.0) {\begin{tabular}{c}concentrated\\sucrose solution\end{tabular}};

  % 7. Distilled water
  \draw[-latex] (6.5, 1.5) -- (5.5, 1.5);
  \node[right] at (6.5, 1.5) {distilled water};

  % Caption
  \node at (3.5, -0.8) {Fig. 2.1};

\end{tikzpicture}

